#!/usr/bin/env node
// Generates the product-surface inventory (version, commands, MCP tools/resources/
// prompts, transports, schemas, test evidence) from the canonical CLI sources, so the
// public product docs and maturity reporting never drift from the installable surface.
// Closes GT-47. Run with --check to fail when the generated files are stale.

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const CLI = path.join(ROOT, 'sdk/cli');
const EN_OUT = path.join(ROOT, 'reference/products/smart-cli/product-inventory.md');
const ES_OUT = path.join(ROOT, 'reference/products/smart-cli/product-inventory.es.md');

// A tool that only launches the MCP server is infrastructure, not a governance tool.
const META_TOOLS = new Set(['evolith-mcp']);

function read(file) {
  return fs.existsSync(file) ? fs.readFileSync(file, 'utf-8') : '';
}

function walk(dir, test) {
  const out = [];
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full, test));
    else if (test(entry.name)) out.push(full);
  }
  return out;
}

function uniqueMatches(content, regex) {
  return [...new Set([...content.matchAll(regex)].map((m) => m[1]))];
}

export function buildInventory(root = ROOT) {
  const cli = path.join(root, 'sdk/cli');
  const pkg = JSON.parse(read(path.join(cli, 'package.json')) || '{}');

  // MCP surfaces — counted from the canonical mcp-server registration sources
  // (GAP DOC-INVENTORY: the server moved to packages/mcp-server in cc5b9c67;
  // the old sdk/cli/src/infrastructure/mcp path was deleted and reported 0/0/0).
  const mcpSrc = path.join(root, 'packages/mcp-server/src');
  const toolSources = walk(path.join(mcpSrc, 'tools'), (f) => f.endsWith('.ts') && !f.includes('.spec.'))
    .map(read).join('\n');
  const tools = uniqueMatches(toolSources, /name:\s*['"](evolith-[a-z-]+)['"]/g)
    .filter((name) => !META_TOOLS.has(name));
  const resources = uniqueMatches(read(path.join(mcpSrc, 'mcp/resources.service.ts')), /uri:\s*['"](evolith:\/\/[^'"]+)['"]/g);
  const prompts = uniqueMatches(read(path.join(mcpSrc, 'mcp/prompts.service.ts')), /name:\s*['"](evolith\/[a-z-]+)['"]/g)
    .filter((name) => name !== 'evolith/unknown');

  const commands = walk(path.join(cli, 'src/commands'), (f) => f.endsWith('.command.ts') && !f.includes('.spec.')).length;
  const schemas = walk(path.join(root, 'src/rulesets/schema'), (f) => f.endsWith('.schema.json')).length;

  // Test evidence — read the generated coverage summary when present.
  let coverage = null;
  const summaryPath = path.join(cli, 'coverage/coverage-summary.json');
  if (fs.existsSync(summaryPath)) {
    try {
      const total = JSON.parse(read(summaryPath)).total;
      coverage = { statements: total.statements.pct, lines: total.lines.pct };
    } catch {
      coverage = null;
    }
  }

  return {
    package: pkg.name || '@beyondnet/evolith-cli',
    version: pkg.version || '0.0.0',
    bin: pkg.bin ? Object.keys(pkg.bin) : [],
    commands,
    tools: tools.length,
    resources: resources.length,
    prompts: prompts.length,
    transports: ['stdio (JSON-RPC 2.0)', 'Streamable HTTP (official MCP SDK)'],
    schemas,
    coverage,
  };
}

function render(inv, es) {
  const t = es
    ? { title: 'Inventario de Superficie del Producto', intro: 'Inventario generado de la superficie instalable de Evolith CLI y MCP. No editar a mano.', field: 'Campo', value: 'Valor', cov: 'Cobertura de statements', covPending: 'pendiente de un run de cobertura' }
    : { title: 'Product Surface Inventory', intro: 'Generated inventory of the installable Evolith CLI and MCP surface. Do not edit by hand.', field: 'Field', value: 'Value', cov: 'Statement coverage', covPending: 'pending a coverage run' };
  const cov = inv.coverage ? `${inv.coverage.statements}% statements · ${inv.coverage.lines}% lines` : t.covPending;
  return `<!-- GENERATED FILE - DO NOT EDIT MANUALLY -->
<!-- Regenerated by .harness/scripts/generate-product-inventory.mjs -->

# ${t.title}

${t.intro}

| ${t.field} | ${t.value} |
|---|---|
| Package | \`${inv.package}@${inv.version}\` |
| Binary | ${inv.bin.map((b) => `\`${b}\``).join(', ')} |
| CLI commands | ${inv.commands} |
| MCP tools | ${inv.tools} |
| MCP resources | ${inv.resources} |
| MCP prompts | ${inv.prompts} |
| MCP transports | ${inv.transports.map((x) => `\`${x}\``).join(', ')} |
| Phase-gate schemas | ${inv.schemas} |
| ${t.cov} | ${cov} |
`;
}

function run() {
  const inv = buildInventory();
  const en = render(inv, false);
  const es = render(inv, true);
  const check = process.argv.includes('--check');

  if (check) {
    const stale = (read(EN_OUT) !== en) || (read(ES_OUT) !== es);
    if (stale) {
      console.error('❌ Product inventory is stale. Run: node .harness/scripts/generate-product-inventory.mjs');
      process.exit(1);
    }
    console.log('✅ Product inventory matches the installable surface.');
    return;
  }

  fs.writeFileSync(EN_OUT, en, 'utf-8');
  fs.writeFileSync(ES_OUT, es, 'utf-8');
  console.log(`✅ Product inventory generated: ${inv.package}@${inv.version} — ${inv.commands} commands, ${inv.tools} tools, ${inv.resources} resources, ${inv.prompts} prompts, ${inv.schemas} schemas.`);
}

run();
